INSERT OR IGNORE INTO content (
         id, slug, kind, title, summary, body, status, sources,
         published_at, created_at, updated_at
       ) VALUES (
         '31b85a22-34eb-4c98-b97a-7f380ce56d98',
         'how-this-site-rebuilds-itself',
         'article',
         'How this site rebuilds itself',
         'Eleven surfaces, a contextual bandit, and a set of guardrails whose job is to stop the optimiser from doing something clever and wrong.',
         '{"blocks":[{"type":"paragraph","text":"Every visitor to this page is served one of several versions of it. Which version depends on what has worked for visitors who arrived the same way, on the same kind of device, at the same time of day."},{"type":"heading","text":"What adapts"},{"type":"list","items":["The palette, typography and spacing, as design tokens on the root element","The headline, the sub-headline and the call to action","The order of the sign-up providers"]},{"type":"paragraph","text":"The decision happens in edge middleware before the page renders, so the HTML that leaves the server is already the right one. There is no flash, because a flash is a layout shift, and layout shift is one of the metrics the optimiser is judged on."}]}',
         'published',
         '[{"url":"https://arxiv.org/abs/1003.0146","title":"A Contextual-Bandit Approach to Personalized News Article Recommendation","publisher":"Li, Chu, Langford, Schapire"}]',
         1785574800000, 1767225600000, 1767225600000
       );

INSERT OR IGNORE INTO content (
         id, slug, kind, title, summary, body, status, sources,
         published_at, created_at, updated_at
       ) VALUES (
         'f7cf4c3d-22f9-4719-8c5e-8ea5478a8f2a',
         'always-valid-p-values',
         'article',
         'Why looking at your experiment is allowed',
         'A fixed-horizon p-value is only valid if you look once. An adaptive system looks continuously, which is why it needs a test built for that.',
         '{"blocks":[{"type":"paragraph","text":"A classical p-value assumes you decided the sample size in advance and looked exactly once. Peek early, stop when it looks good, and the false-positive rate is no longer the number written on the tin."},{"type":"paragraph","text":"An adaptive system peeks constantly — that is what adapting is. The fix is a test whose guarantee holds at every stopping time rather than at one, which is what a mixture sequential probability ratio test provides."}]}',
         'published',
         '[{"url":"https://arxiv.org/abs/1512.04922","title":"Always Valid Inference: Continuous Monitoring of A/B Tests","publisher":"Johari, Pekelis, Walsh"}]',
         1786525200000, 1767225600000, 1767225600000
       );

